df = pd.read_parquet("hf://datasets/Kyle1668/LLM-TTA-Augmentation-Logs/" + splits["BOSS_Toxicity_ID_BERT_ICR"]) 
df = df[["original_text", "label"]]
#df = df.sample(n=100, replace=True, random_state=42)

from datasets import Dataset, DatasetDict, ClassLabel, Features, Value

def build_dataset_from_df(
    df: pd.DataFrame,
    test_size: float = 0.2,
    seed: int = 42
) -> DatasetDict:
    # 1) Keep only the two columns
    df = df[["original_text", "label"]]

    # 2) Define schema: text is string, label is ClassLabel with names [0,1]
    features = Features({
        "original_text": Value("string"),
        "label": ClassLabel(names=["0", "1"]),
    })

    # 3) Load with those features
    ds = Dataset.from_pandas(df, preserve_index=False, features=features)

    # 4) Now stratify by that ClassLabel column
    split = ds.train_test_split(
        test_size=test_size,
        seed=seed,
        stratify_by_column="label"
    )

    return DatasetDict({"train": split["train"], "test": split["test"]})

# Usage
datasets = build_dataset_from_df(df, test_size=0.20)


# 2. Load tokenizer & binary‐classification model
model_name = "meta-llama/Llama-2-7b-hf"
tokenizer = LlamaTokenizer.from_pretrained(model_name)
tokenizer.pad_token = tokenizer.eos_token
tokenizer.pad_token_id = tokenizer.eos_token_id

model = LlamaForSequenceClassification.from_pretrained(
    model_name,
    num_labels=2,               # <-- change to 2
    load_in_8bit=True,
    device_map="auto"
)
model.config.pad_token_id = tokenizer.pad_token_id


# 3. Prepare model for LoRA + k-bit training
model = prepare_model_for_kbit_training(model)
lora_config = LoraConfig(
    r=8,
    lora_alpha=16,
    target_modules=["q_proj", "v_proj"],
    lora_dropout=0.05,
    bias="none",
    task_type="SEQ_CLS"
)
model = get_peft_model(model, lora_config)

# 4. Tokenization function
def tokenize(batch):
    return tokenizer(
        batch["original_text"],
        padding="max_length",
        max_length=512,
        truncation=True
    )

# 5. Prepare datasets
datasets = datasets.map(tokenize, batched=True)
datasets = datasets.rename_column("label", "labels")
datasets.set_format("torch", columns=["input_ids", "attention_mask", "labels"])

# 6. Training arguments
training_args = TrainingArguments(
    output_dir="./lora_binary_sentiment",
    per_device_train_batch_size=2,
    per_device_eval_batch_size=2,
    num_train_epochs=3,
    learning_rate=1e-4,
    do_eval=True,
    eval_strategy="epoch",
    save_strategy="no",
    logging_steps=10,
    fp16=True,
    remove_unused_columns=False,
)

# 7. Trainer initialization
def compute_metrics(eval_pred):
    logits, labels = eval_pred
    preds = torch.argmax(torch.tensor(logits), dim=-1)
    accuracy = (preds == torch.tensor(labels)).float().mean()
    return {"accuracy": accuracy.item()}

trainer = Trainer(
    model=model,
    args=training_args,
    train_dataset=datasets["train"],
    eval_dataset=datasets["test"],
    compute_metrics=compute_metrics,
    tokenizer=tokenizer,
)


# 8. Fine-tune
trainer.train()

# 9. Save LoRA adapters
model.save_pretrained("./lora_binary_adapter")
tokenizer.save_pretrained("./lora_binary_adapter_tokenize")